local M = {}
M.state = 0
local function playSound(Name, volume)
	--sound = "audio/".. Name ..".ogg"
	Engine.Audio.playOnce("AudioGui", Name, {volume = volume})
	--uihooks.trigger('ChangeState', 'menu-subrp-test')
end
-- data = {audio = "audio/test.ogg" or nil, title = "", desc = "", image = ""}
local function AchievementUI(data_json)
	if M.state < 2 then
		TriggerServerEvent("AchivmentReLoad","")
		return
	end
	local data = jsonDecode(data_json)
	if data == nil then
		log("E", "AchievementUI", "invalid data use \" in json")
		return
	end
	if data and data.audio then
		playSound(data.audio, 0.8)
	else
		playSound("audio/steam.mp3", 0.8)
	end
	local desc = nil
	if data and data.desc then
		desc = data.desc
	end
	local image = nil
	if data and data.image then
		image = data.image
	end
	local title = nil
	if data and data.title then
		title = data.title
	else
		title = "Error Steam Achievement"
	end
	guihooks.trigger('triggerAchievement', {title = title, desc = desc, image = image})
	log('D', 'onNotify', "okey")
	if M.state >= 2 then
		TriggerServerEvent("AchivmentAcceptReg", jsonEncode({name = data.name}))
	end
end

local function onExtensionLoaded()
	AddEventHandler("AchievementUIRun", AchievementUI)
end

local function onWorldReadyState(state)
	M.state = state
end

M.onWorldReadyState = onWorldReadyState
M.onExtensionLoaded = onExtensionLoaded
M.playSound = playSound
M.Notify = AchievementUI

return M;